const AudioFX = {
  ctx:null, on:false, padGain:null, padOsc:[],
  ensure(){ if(!this.ctx){ const AC=window.AudioContext||window.webkitAudioContext; this.ctx=new AC();
      this.padGain=this.ctx.createGain(); this.padGain.gain.value=0; this.padGain.connect(this.ctx.destination);
      [55,82.5,110].forEach((f,i)=>{ const o=this.ctx.createOscillator(); o.type="sine"; o.frequency.value=f;
        const g=this.ctx.createGain(); g.gain.value=i===0?0.5:0.25; o.connect(g); g.connect(this.padGain); o.start(); });
    } if(this.ctx.state==="suspended") this.ctx.resume(); },
  toggle(){ this.on=!this.on; this.ensure(); this.padGain.gain.linearRampToValueAtTime(this.on?0.035:0,this.ctx.currentTime+0.6);
    return this.on; },
  blip(f=660){ if(!this.on||!this.ctx) return; const o=this.ctx.createOscillator(),g=this.ctx.createGain();
    o.type="triangle"; o.frequency.value=f; g.gain.setValueAtTime(0.06,this.ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001,this.ctx.currentTime+0.35);
    o.connect(g); g.connect(this.ctx.destination); o.start(); o.stop(this.ctx.currentTime+0.4); },
};

