let CAM={x:0,y:0,z:1,tx:0,ty:0,tz:1};
function camTo(x,y,z){ CAM.tx=x; CAM.ty=y; CAM.tz=z; }
function camTick(dt){ const k=1-Math.pow(0.001,dt); CAM.x+=(CAM.tx-CAM.x)*k; CAM.y+=(CAM.ty-CAM.y)*k; CAM.z+=(CAM.tz-CAM.z)*k; }
function P(wx,wy){ return [ (wx-CAM.x)*CAM.z+W/2, (wy-CAM.y)*CAM.z+H/2 ]; }

function rr(c,x,y,w,h,r){ c.beginPath(); c.moveTo(x+r,y); c.arcTo(x+w,y,x+w,y+h,r); c.arcTo(x+w,y+h,x,y+h,r); c.arcTo(x,y+h,x,y,r); c.arcTo(x,y,x+w,y,r); c.closePath(); }

function vignette(){ const g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*0.45,W/2,H/2,Math.max(W,H)*0.75);
  g.addColorStop(0,"#00000000"); g.addColorStop(1,"#02090BCC"); ctx.fillStyle=g; ctx.fillRect(0,0,W,H); }

function starfield(seedN=140){ ctx.save(); let s=1234; const rnd=()=>{ s=(s*16807)%2147483647; return s/2147483647; };
  for(let i=0;i<seedN;i++){ const x=rnd()*W,y=rnd()*H,r=rnd()*1.3+0.3,a=rnd()*0.35+0.08;
    ctx.fillStyle=`rgba(150,200,205,${a})`; ctx.beginPath(); ctx.arc(x,y,r,0,7); ctx.fill(); } ctx.restore(); }

function graticule(){ ctx.save(); ctx.strokeStyle="rgba(20,70,80,0.35)"; ctx.lineWidth=1;
  for(let lon=-180;lon<=180;lon+=30){ const [x1,y1]=P(lon,-85),[x2,y2]=P(lon,85);
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke(); }
  for(let lat=-60;lat<=80;lat+=20){ const [x1,y1]=P(-180,-lat),[x2,y2]=P(190,-lat);
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke(); } ctx.restore(); }

function glowCircle(x,y,r,color,glow=14,alpha=1){ ctx.save(); ctx.globalAlpha=alpha;
  const g=ctx.createRadialGradient(x,y,r*0.2,x,y,r+glow); g.addColorStop(0,color); g.addColorStop(1,"#00000000");
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,r+glow,0,7); ctx.fill(); ctx.restore(); }

function arrowHead(x,y,ang,color,alpha,s){ ctx.save(); ctx.globalAlpha=alpha; ctx.fillStyle=color;
  ctx.beginPath(); ctx.moveTo(x,y);
  ctx.lineTo(x-s*Math.cos(ang-0.42),y-s*Math.sin(ang-0.42));
  ctx.lineTo(x-s*Math.cos(ang+0.42),y-s*Math.sin(ang+0.42)); ctx.fill(); ctx.restore(); }
function drawEdge(ax,ay,bx,by,w,color,alpha=1,dash=null,arrow=true){ ctx.save(); ctx.globalAlpha=alpha;
  ctx.strokeStyle=color; ctx.lineWidth=Math.max(0.6,w); if(dash) ctx.setLineDash(dash);
  ctx.beginPath(); ctx.moveTo(ax,ay); ctx.lineTo(bx,by); ctx.stroke();
  if(arrow) arrowHead(bx,by,Math.atan2(by-ay,bx-ax),color,alpha,5+2.2*w);
  ctx.restore(); }

function arcCtrl(ax,ay,bx,by){ const mx=(ax+bx)/2,my=(by+by)/2,dx=bx-ax,dy=by-ay,d=Math.hypot(dx,dy)||1;
  return [mx-dy/d*d*0.18, my+dx/d*d*0.18]; }
function drawArc(ax,ay,bx,by,w,color,alpha=1,dash=null,arrow=true){ const [cx,cy]=arcCtrl(ax,ay,bx,by);
  ctx.save(); ctx.globalAlpha=alpha; ctx.strokeStyle=color; ctx.lineWidth=Math.max(0.6,w);
  if(dash) ctx.setLineDash(dash);
  ctx.beginPath(); ctx.moveTo(ax,ay); ctx.quadraticCurveTo(cx,cy,bx,by); ctx.stroke();
  if(arrow){ const p=0.9, u=1-p;
    const ex=u*u*ax+2*u*p*cx+p*p*bx, ey=u*u*ay+2*u*p*cy+p*p*by;
    const dx=2*u*(cx-ax)+2*p*(bx-cx), dy=2*u*(cy-ay)+2*p*(by-cy);
    arrowHead(ex,ey,Math.atan2(dy,dx),color,alpha,4.5+2.2*w); }
  ctx.restore(); }
function packetsArc(ax,ay,bx,by,t,n=2,color=AMBER){ const [cx,cy]=arcCtrl(ax,ay,bx,by);
  ctx.save(); ctx.fillStyle=color;
  for(let i=0;i<n;i++){ const p=((t*0.25+i/n)%1); const u=1-p;
    const x=u*u*ax+2*u*p*cx+p*p*bx, y=u*u*ay+2*u*p*cy+p*p*by;
    ctx.globalAlpha=Math.sin(p*Math.PI); ctx.beginPath(); ctx.arc(x,y,2.2,0,7); ctx.fill(); } ctx.restore(); }
function packets(ax,ay,bx,by,t,n=3,color=AMBER){ ctx.save(); ctx.fillStyle=color;
  for(let i=0;i<n;i++){ const p=((t*0.25+i/n)%1); const x=ax+(bx-ax)*p, y=ay+(by-ay)*p;
    ctx.globalAlpha=Math.sin(p*Math.PI); ctx.beginPath(); ctx.arc(x,y,2.2,0,7); ctx.fill(); } ctx.restore(); }

function label(x,y,text,color=TXT,size=12,align="center",bold=false){ ctx.save();
  ctx.font=`${bold?"700 ":""}${size}px Inter,system-ui,sans-serif`; ctx.fillStyle=color; ctx.textAlign=align;
  ctx.fillText(text,x,y); ctx.restore(); }

function panel(x,y,w,h,alpha=0.85){ ctx.save(); ctx.globalAlpha=alpha; ctx.fillStyle="#0E242C";
  rr(ctx,x,y,w,h,12); ctx.fill(); ctx.strokeStyle="#1B3A44"; ctx.lineWidth=1; ctx.stroke(); ctx.restore(); }

function meter(x,y,w,h,frac,color,txtL,txtR){ ctx.save(); ctx.fillStyle="#123038"; rr(ctx,x,y,w,h,6); ctx.fill();
  ctx.fillStyle=color; if(frac>0.005){ rr(ctx,x,y,w*Math.min(1,frac),h,6); ctx.fill(); }
  label(x+8,y+h-6,txtL,MUT,10,"left"); label(x+w-8,y+h-6,txtR,TXT,11,"right",true); ctx.restore(); }

function ease(p){ return p<0.5 ? 2*p*p : 1-Math.pow(-2*p+2,2)/2; }

/* ================= PROYECCIÓN MUNDO ================= */
const WORLD={x0:-185,x1:195,y0:-88,y1:92};
function fitWorld(pad=0.06){ const z=Math.min(W/(WORLD.x1-WORLD.x0),H/(WORLD.y1-WORLD.y0))*(1-pad);
  camTo((WORLD.x0+WORLD.x1)/2,(WORLD.y0+WORLD.y1)/2,z); }
function worldPos(node){ return [node.lon+node.jlon, -(node.lat+node.jlat)]; }

/* ================= DATOS PREPROCESADOS ================= */
const NODES=DATA.nodes.map(nd=>({...nd, active:false, alpha:0}));
const EIDX={}; NODES.forEach((nd,i)=>EIDX[nd.id]=i);
const EDGES_B=DATA.edgesB.map(e=>({...e, a:NODES[EIDX[e.s]], b:NODES[EIDX[e.t]], alpha:0}));
const EDGES_A=DATA.edgesA.map(e=>({...e, a:NODES[EIDX[e.s]], b:NODES[EIDX[e.t]], alpha:0}));
