/* ---------- utilidad: grafo de juguete ---------- */
function toyGraph(n,radius,cx,cy){ const nodes=[];
  for(let i=0;i<n;i++){ const a=-Math.PI/2+i*2*Math.PI/n;
    nodes.push({x:cx+Math.cos(a)*radius,y:cy+Math.sin(a)*radius,id:i,_r:radius,_a:a}); }
  return nodes; }
function relayout(nodes,cx,cy){ nodes.forEach(nd=>{ nd.x=cx+Math.cos(nd._a)*nd._r; nd.y=cy+Math.sin(nd._r&&nd._a!==undefined?nd._a:0)*nd._r; }); }
function toyEdges(nodes,pairs){ return pairs.map(([a,b])=>({a:nodes[a],b:nodes[b]})); }

